-- Generated by npm run auth:schema:d1 from the pinned identity configuration.
-- Apply explicitly to D1 before enabling accounts. Does not migrate prototype notes.
create table "yumunio_users" ("id" text not null primary key, "name" text not null, "email" text not null unique, "emailVerified" integer not null, "image" text, "createdAt" date not null, "updatedAt" date not null);

create table "yumunio_auth_sessions" ("id" text not null primary key, "expiresAt" date not null, "token" text not null unique, "createdAt" date not null, "updatedAt" date not null, "ipAddress" text, "userAgent" text, "userId" text not null references "yumunio_users" ("id") on delete cascade, "activeOrganizationId" text);

create table "yumunio_auth_accounts" ("id" text not null primary key, "accountId" text not null, "providerId" text not null, "userId" text not null references "yumunio_users" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" date, "refreshTokenExpiresAt" date, "scope" text, "password" text, "createdAt" date not null, "updatedAt" date not null);

create table "yumunio_auth_verifications" ("id" text not null primary key, "identifier" text not null, "value" text not null, "expiresAt" date not null, "createdAt" date not null, "updatedAt" date not null);

create table "yumunio_workspaces" ("id" text not null primary key, "name" text not null, "slug" text not null unique, "logo" text, "createdAt" date not null, "metadata" text);

create table "yumunio_memberships" ("id" text not null primary key, "organizationId" text not null references "yumunio_workspaces" ("id") on delete cascade, "userId" text not null references "yumunio_users" ("id") on delete cascade, "role" text not null, "createdAt" date not null);

create table "yumunio_workspace_invitations" ("id" text not null primary key, "organizationId" text not null references "yumunio_workspaces" ("id") on delete cascade, "email" text not null, "role" text, "status" text not null, "expiresAt" date not null, "createdAt" date not null, "inviterId" text not null references "yumunio_users" ("id") on delete cascade);

create table "yumunio_auth_rate_limits" ("id" text not null primary key, "key" text not null unique, "count" integer not null, "lastRequest" bigint not null);

create index "yumunio_auth_sessions_userId_idx" on "yumunio_auth_sessions" ("userId");

create index "yumunio_auth_accounts_userId_idx" on "yumunio_auth_accounts" ("userId");

create index "yumunio_auth_verifications_identifier_idx" on "yumunio_auth_verifications" ("identifier");

create index "yumunio_memberships_organizationId_idx" on "yumunio_memberships" ("organizationId");

create index "yumunio_memberships_userId_idx" on "yumunio_memberships" ("userId");

create index "yumunio_workspace_invitations_organizationId_idx" on "yumunio_workspace_invitations" ("organizationId");

create index "yumunio_workspace_invitations_email_idx" on "yumunio_workspace_invitations" ("email");
-- Account-owned content only. Apply explicitly; never imports or replaces prototype snapshots.
-- SDK-owned identity tables remain separate. Every read/write verifies the live workspace and membership.
CREATE TABLE IF NOT EXISTS yumunio_account_content (
  workspace_id TEXT NOT NULL PRIMARY KEY,
  revision INTEGER NOT NULL CHECK (revision >= 1 AND revision <= 9007199254740991),
  payload_json TEXT NOT NULL CHECK (length(CAST(payload_json AS BLOB)) <= 900000)
);
-- Additive transport schema. Existing raw JSON rows remain readable without conversion.
CREATE TABLE IF NOT EXISTS yumunio_content_chunks (
  workspace_id TEXT NOT NULL,
  revision INTEGER NOT NULL CHECK (revision >= 1 AND revision <= 9007199254740991),
  ordinal INTEGER NOT NULL CHECK (ordinal >= 0 AND ordinal < 32),
  payload_text TEXT NOT NULL CHECK (length(CAST(payload_text AS BLOB)) >= 1 AND length(CAST(payload_text AS BLOB)) <= 256000),
  PRIMARY KEY (workspace_id, revision, ordinal)
);
CREATE TABLE IF NOT EXISTS yumunio_content_guards (
  id TEXT NOT NULL PRIMARY KEY,
  ok INTEGER NOT NULL CHECK (ok = 1)
);

-- Collaboration state and encrypted durable mail. Apply explicitly alongside the SDK and content schema.
CREATE TABLE IF NOT EXISTS yumunio_collaboration_invitations (
  id TEXT NOT NULL PRIMARY KEY,
  workspace_id TEXT NOT NULL,
  generation INTEGER NOT NULL CHECK (generation >= 1),
  invitation_json TEXT NOT NULL CHECK (length(CAST(invitation_json AS BLOB)) <= 10000),
  issuer_membership_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('pending','accepted','revoked'))
);
CREATE INDEX IF NOT EXISTS yumunio_collaboration_invites_workspace ON yumunio_collaboration_invitations (workspace_id);
CREATE TABLE IF NOT EXISTS yumunio_mail_jobs (
  id TEXT NOT NULL PRIMARY KEY,
  dedupe_key TEXT NOT NULL UNIQUE,
  payload_ciphertext TEXT NOT NULL CHECK (length(CAST(payload_ciphertext AS BLOB)) <= 140000),
  payload_digest TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('queued','leased','accepted','dead','cancelled')),
  attempts INTEGER NOT NULL CHECK (attempts >= 0),
  available_at TEXT NOT NULL,
  lease_id TEXT,
  lease_until TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  invitation_id TEXT,
  invitation_generation INTEGER
);
CREATE INDEX IF NOT EXISTS yumunio_mail_jobs_due ON yumunio_mail_jobs (status,available_at);
CREATE INDEX IF NOT EXISTS yumunio_mail_jobs_invitation ON yumunio_mail_jobs (invitation_id);
-- D1 batch: a failed affected-row assertion must abort and roll back the whole batch.
CREATE TABLE IF NOT EXISTS yumunio_transaction_guards (
  id TEXT NOT NULL PRIMARY KEY,
  ok INTEGER NOT NULL CONSTRAINT yumunio_transaction_guard CHECK (ok = 1)
);

-- Personal display preferences only; no workspace content or credentials.
CREATE TABLE IF NOT EXISTS yumunio_account_preferences (
 account_id TEXT NOT NULL PRIMARY KEY,
 revision INTEGER NOT NULL CHECK (revision >= 1 AND revision <= 9007199254740991),
 preferences_json TEXT NOT NULL CHECK (length(CAST(preferences_json AS BLOB)) <= 4096)
);

-- Explicit migration. Plaintext bearer tokens are never stored. SDK identity tables are joined, not altered.
CREATE TABLE IF NOT EXISTS yumunio_api_tokens (
  id TEXT NOT NULL PRIMARY KEY CHECK (length(id) = 32),
  account_id TEXT NOT NULL,
  workspace_id TEXT NOT NULL,
  page_id TEXT NOT NULL,
  membership_id TEXT NOT NULL,
  actor_role TEXT NOT NULL CHECK (actor_role IN ('owner','admin','member','guest')),
  name TEXT NOT NULL CHECK (length(name) >= 1 AND length(name) <= 80),
  scopes_json TEXT NOT NULL CONSTRAINT yumunio_api_token_scopes CHECK (scopes_json IN ('["page:read"]','["page:read","document:read"]','["page:read","document:read","document:write"]','["page:read","mcp:connect"]','["page:read","document:read","mcp:connect"]','["page:read","document:read","document:write","mcp:connect"]')),
  token_hash TEXT NOT NULL CHECK (length(token_hash) = 64),
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  revoked_at TEXT,
  version INTEGER NOT NULL CHECK (version >= 1 AND version <= 9007199254740991),
  request_id TEXT NOT NULL,
  request_digest TEXT NOT NULL CHECK (length(request_digest) = 64),
  active_slot INTEGER CHECK (active_slot >= 1 AND active_slot <= 20),
  metadata_slot INTEGER NOT NULL CHECK (metadata_slot >= 1 AND metadata_slot <= 50),
  UNIQUE (account_id,request_id),
  UNIQUE (account_id,active_slot),
  UNIQUE (account_id,metadata_slot),
  CHECK (expires_at > created_at),
  CHECK (revoked_at IS NULL OR active_slot IS NULL)
);

CREATE TABLE IF NOT EXISTS yumunio_webhook_approvals (
 profile_hash TEXT NOT NULL PRIMARY KEY,
 approved_by TEXT NOT NULL,
 approved_at TEXT NOT NULL,
 revoked_at TEXT,
 version INTEGER NOT NULL CHECK(version>=1 AND version<9007199254740991)
);
CREATE TABLE IF NOT EXISTS yumunio_webhook_subscriptions (
 id TEXT NOT NULL PRIMARY KEY,
 workspace_id TEXT NOT NULL,
 page_id TEXT NOT NULL,
 issuer_account_id TEXT NOT NULL,
 membership_id TEXT NOT NULL,
 actor_role TEXT NOT NULL CHECK(actor_role IN ('owner','admin','member','guest')),
 profile_hash TEXT NOT NULL,
 authority_fingerprint TEXT NOT NULL,
 start_version INTEGER NOT NULL CHECK(start_version>=1 AND start_version<9007199254740991),
 status TEXT NOT NULL CHECK(status IN ('active','paused','cancelled','quarantined')),
 reason TEXT CHECK(reason IN ('capacity','restore','authority','profile','approval','user')),
 missed_from_version INTEGER,
 missed_through_version INTEGER,
 gap_acknowledged_at TEXT,
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 version INTEGER NOT NULL CHECK(version>=1 AND version<9007199254740991),
 UNIQUE(workspace_id,page_id),
 CHECK((missed_from_version IS NULL AND missed_through_version IS NULL) OR (missed_from_version IS NOT NULL AND missed_from_version>=1 AND missed_through_version IS NOT NULL AND missed_through_version>=missed_from_version))
);
CREATE TABLE IF NOT EXISTS yumunio_webhook_jobs (
 event_id TEXT NOT NULL PRIMARY KEY,
 subscription_id TEXT NOT NULL,
 subscription_version INTEGER NOT NULL CHECK(subscription_version>=1),
 profile_hash TEXT NOT NULL,
 workspace_id TEXT NOT NULL,
 page_id TEXT NOT NULL,
 page_version INTEGER NOT NULL CHECK(page_version>=1 AND page_version<9007199254740991),
 event_type TEXT NOT NULL CONSTRAINT yumunio_webhook_event_type CHECK(event_type IN ('page.updated','page.title.updated','page.document.updated','page.created','page.moved','page.trashed','page.restored')),
 occurred_at TEXT NOT NULL,
 payload_json TEXT NOT NULL CHECK(length(payload_json)<=1024),
 payload_digest TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('queued','leased','delivered','failed','cancelled','quarantined')),
 attempts INTEGER NOT NULL CHECK(attempts>=0 AND attempts<=4),
 next_attempt_at TEXT NOT NULL,
 lease_id TEXT,
 lease_until TEXT,
 last_code TEXT,
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 version INTEGER NOT NULL CHECK(version>=1 AND version<9007199254740991),
 CONSTRAINT yumunio_webhook_job_scope UNIQUE(subscription_id,subscription_version,page_id,page_version,event_type),
 CHECK((status='leased' AND lease_id IS NOT NULL AND lease_until IS NOT NULL) OR (status<>'leased' AND lease_id IS NULL AND lease_until IS NULL))
);
CREATE INDEX IF NOT EXISTS yumunio_webhook_due ON yumunio_webhook_jobs(status,next_attempt_at,event_id);
CREATE INDEX IF NOT EXISTS yumunio_webhook_scope_jobs ON yumunio_webhook_jobs(subscription_id,status);
CREATE TABLE IF NOT EXISTS yumunio_webhook_guards (
 id TEXT NOT NULL PRIMARY KEY,
 ok INTEGER NOT NULL CHECK(ok=1)
);
CREATE TABLE IF NOT EXISTS yumunio_room_presence (
 id VARCHAR(32) NOT NULL PRIMARY KEY,
 workspace_id VARCHAR(128) NOT NULL,
 page_id VARCHAR(128) NOT NULL,
 epoch VARCHAR(128) NOT NULL,
 account_id VARCHAR(128) NOT NULL,
 membership_id VARCHAR(128) NOT NULL,
 session_id VARCHAR(128) NOT NULL,
 actor_role VARCHAR(16) NOT NULL CHECK (actor_role IN ('owner','admin','member','guest')),
 client_id VARCHAR(36) NOT NULL,
 sequence BIGINT NOT NULL CHECK (sequence>=1 AND sequence<9007199254740991),
 document_version BIGINT NOT NULL CHECK (document_version>=1 AND document_version<9007199254740991),
 cursor_json TEXT NOT NULL,
 expires_at VARCHAR(24) NOT NULL,
 slot INTEGER NOT NULL CHECK (slot>=0 AND slot<64),
 account_slot INTEGER NOT NULL CHECK (account_slot>=0 AND account_slot<8),
 UNIQUE (workspace_id,page_id,slot),
 UNIQUE (workspace_id,page_id,account_id,account_slot)
);
CREATE INDEX IF NOT EXISTS yumunio_room_presence_expiry ON yumunio_room_presence(expires_at);

CREATE TABLE IF NOT EXISTS yumunio_backup_jobs (
 id TEXT NOT NULL PRIMARY KEY,
 request_key TEXT NOT NULL UNIQUE,
 status TEXT NOT NULL CHECK(status IN ('queued','leased','complete','failed','cancelled')),
 phase TEXT NOT NULL,
 state_json TEXT NOT NULL CHECK(length(CAST(state_json AS BLOB))<=1000000),
 attempts INTEGER NOT NULL CHECK(attempts>=0),
 lease_id TEXT,
 lease_until TEXT,
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 error_code TEXT
);
CREATE INDEX IF NOT EXISTS yumunio_backup_jobs_due ON yumunio_backup_jobs(status,lease_until);
CREATE TABLE IF NOT EXISTS yumunio_backup_fragments (
 job_id TEXT NOT NULL,
 resource TEXT NOT NULL,
 ordinal INTEGER NOT NULL CHECK(ordinal>=0),
 descriptor_json TEXT NOT NULL CHECK(length(CAST(descriptor_json AS BLOB))<=8192),
 ciphertext_base64 TEXT NOT NULL CHECK(length(CAST(ciphertext_base64 AS BLOB))<=1500000),
 stored INTEGER NOT NULL CHECK(stored IN (0,1)),
 PRIMARY KEY(job_id,resource,ordinal)
);
CREATE TABLE IF NOT EXISTS yumunio_backup_guards (
 id TEXT NOT NULL PRIMARY KEY,
 ok INTEGER NOT NULL CHECK(ok=1)
);
CREATE TABLE IF NOT EXISTS yumunio_recovery_state (
 id INTEGER NOT NULL PRIMARY KEY CHECK(id=1),
 restore_id TEXT NOT NULL,
 manifest_digest TEXT NOT NULL,plan_digest TEXT NOT NULL,target_profile_id TEXT NOT NULL,prepared_at TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('restoring','ready')),
 row_cursor INTEGER NOT NULL CHECK(row_cursor>=0),
 row_count INTEGER NOT NULL CHECK(row_count>=0),
 updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS yumunio_backup_artifacts (
 backup_id TEXT NOT NULL, object_key TEXT NOT NULL,
 cipher_checksum TEXT NOT NULL, cipher_size INTEGER NOT NULL CHECK(cipher_size>=1 AND cipher_size<=1048592),
 confirmed INTEGER NOT NULL CHECK(confirmed IN (0,1)), created_at TEXT NOT NULL,
 PRIMARY KEY(backup_id,object_key)
);
CREATE TABLE IF NOT EXISTS yumunio_backup_cleanup_approval (
 id INTEGER NOT NULL PRIMARY KEY CHECK(id=1), policy_digest TEXT NOT NULL,
 approved_by TEXT NOT NULL, approved_at TEXT NOT NULL, revoked_at TEXT,
 version INTEGER NOT NULL CHECK(version>=1)
);
CREATE TABLE IF NOT EXISTS yumunio_backup_cleanups (
 id TEXT NOT NULL PRIMARY KEY, request_key TEXT NOT NULL UNIQUE, backup_id TEXT NOT NULL UNIQUE,
 policy_digest TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','leased','complete','blocked','failed')),
 reason TEXT NOT NULL CHECK(reason IN ('retention','failed')), object_cursor INTEGER NOT NULL CHECK(object_cursor>=0),
 plan_json TEXT NOT NULL CHECK(length(CAST(plan_json AS BLOB))<=1000000),
 lease_id TEXT, lease_until TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, error_code TEXT
);
